  const rides = {};
  for (const [k, t] of [["attachments", "file"], ["task_references", "task"], ["skills", "skill"], ["connectors", "conn"]])
    if (tv(t).length)
      rides[k] = tv(t);
  const a = jattr({ ...o.sendArgs || {}, ...rides, ...o.taskId ? { task_id: o.taskId } : {}, ...o.confirm ? { confirm: true } : {} });
