function openWebUrl(url) {
  if (process.env.MANUS_NO_OPEN === "1") {
    process.stderr.write(`[manus] (test) would open ${url}
`);
    return Promise.resolve(true);
  }
  return new Promise((resolve) => {
    let settled = false;
    const done = (ok, why) => {
      if (settled)
        return;
      settled = true;
      if (!ok)
        process.stderr.write(`[manus] open web failed: ${why || "unknown"}
`);
      resolve(ok);
    };
    try {
      const [cmd, argv] = webOpenCommand(process.platform, url);
      const p = spawn2(cmd, argv, { stdio: "ignore" });
      p.on("error", (e) => done(false, String(e)));
      p.on("exit", (code, sig) => done(code === 0, `open exited ${code ?? sig}`));
      setTimeout(() => {
        try {
          p.unref();
        } catch {}
        done(true);
      }, OPEN_WAIT_MS);
    } catch (e) {
      done(false, String(e));
    }
  });
}
